export function accessEncounterRoute(route){
 if(!route||route.encounterAccessVersion===1||!route.tables?.length)return route;
 const edits=ACCESS_CHANGES[route.room];if(!edits)return route;
 return {...route,encounterAccessVersion:1,tables:route.tables.map(t=>{const slots=t.slots.map(s=>({...s}));for(const e of edits[t.phase]||[]){if(slots.some(s=>s.species_id===e.id))continue;if(e.from){const s=slots.find(s=>s.species_id===e.from);if(!s)throw Error('Missing habitat donor: '+route.room+' '+e.from);s.species_id=e.id;s.authoredSlot=true;s.firstFormAccess=true;}else{const donor=slots.find(s=>s.species_id===e.take);if(!donor||donor.weight<=e.weight)throw Error('Missing habitat weight: '+route.room);donor.weight-=e.weight;slots.push({species_id:e.id,min_level:e.min,max_level:e.max,weight:e.weight,rarity:'Uncommon',authoredSlot:true,firstFormAccess:true});}}return {...t,slots};})};
}
